window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f1ca5bb0cdf1176b"]={"versions": [{"id": "FIG-f1ca5bb0cdf1176b", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses innerhalb des Funktionsschritts „Verify inputs of the forward function“ der Funktion <code>E2E_P22Forward()</code> im AUTOSAR E2E-Protokoll (Profile 22).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontext</strong>: <code>E2E_P22Forward()</code>\n</li><li><strong>Eingangsparameter / Entitäten</strong>:\n<ul class=\"fig-list\"><li><code>Config</code>: Zeiger auf Konfigurationsstruktur (<code>E2E_P22ConfigType</code>), enthält <code>DataLength</code>\n</li><li><code>State</code>: Zeiger auf Zustandsstruktur (<code>E2E_P22ProtectStateType</code>)\n</li><li><code>Data</code>: Zeiger auf die Nutzdaten (<code>uint8*</code>)\n</li><li><code>ForwardStatus</code>: Status des Weiterleitungsaufrufs (<code>E2E_PCheckStatusType</code>)\n</li><li><code>Length</code>: Länge der übergebenen Daten (<code>uint16</code>)\n</li><li><code>Offset</code>: Offset-Konfiguration innerhalb der Datenstruktur\n</li></ul>\n</li><li><strong>Entscheidungsknoten (Decision Nodes)</strong>:\n<ul class=\"fig-list\"><li>Null-Pointer-Prüfung aller Zeigerparameter (<code>Config</code>, <code>State</code>, <code>Data</code>, <code>ForwardStatus</code>)\n</li><li>Plausibilitätsprüfung für <code>Length</code> und Gültigkeitsprüfung von <code>ForwardStatus</code>\n</li></ul>\n</li><li><strong>Aktivitätsendknoten (Flow Final Nodes)</strong>:\n<ul class=\"fig-list\"><li><code>no input</code>: Fehlerpfad bei Null-Pointer (führt zu <code>E2E_E_INPUTERR_NULL</code>)\n</li><li><code>wrong input</code>: Fehlerpfad bei ungültiger Datenlänge oder fehlenden Neudaten (führt zu <code>E2E_E_INPUTERR_WRONG</code>)\n</li><li><code>input ok</code>: Erfolgreiche Validierung aller Eingabeparameter (führt zur Fortsetzung der Funktionsausführung)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Beginn am Startknoten der Aktivität <code>E2E_P22Forward()</code>.\n</li><li>Erste Verzweigung (Null-Pointer-Check):\n<ul class=\"fig-list\"><li>Auswertung der Guard-Bedingung <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL) &amp;&amp; (ForwardStatus != NULL)</code>.\n</li><li>Bei <code>[FALSE]</code> verzweigt der Kontrollfluss zum Aktivitätsendknoten <code>no input</code>.\n</li><li>Bei <code>[TRUE]</code> führt der Kontrollfluss zum zweiten Entscheidungsknoten.\n</li></ul>\n</li><li>Zweite Verzweigung (Plausibilitäts-Check):\n<ul class=\"fig-list\"><li>Auswertung der Guard-Bedingung <code>Length == Config-&gt;DataLength/8 &amp;&amp; Length &gt;= Offset+2 &amp;&amp; (ForwardStatus != E2E_P_NONEWDATA)</code>.\n</li><li>Bei <code>[FALSE]</code> verzweigt der Kontrollfluss zum Aktivitätsendknoten <code>wrong input</code>.\n</li><li>Bei <code>[TRUE]</code> führt der Kontrollfluss zum Aktivitätsendknoten <code>input ok</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert normativ (referenziert über <code>[PRS_E2E_00636]</code>) das genaue Validierungsverhalten von <code>E2E_P22Forward()</code>. Implementierungen müssen zwingend zuerst sämtliche Zeiger auf Ungleichheit mit <code>NULL</code> prüfen, bevor auf Member von <code>Config</code> zugegriffen werden darf (Vermeidung von Null-Pointer-Dereferenzierungen). Nur wenn sowohl die Datenlänge exakt <code>Config-&gt;DataLength/8</code> entspricht, mindestens <code>Offset+2</code> beträgt und <code>ForwardStatus</code> ungleich <code>E2E_P_NONEWDATA</code> ist, gilt die Eingabe als gültig (<code>input ok</code>). Andernfalls sind die spezifischen Fehlercodes für Null-Pointer bzw. ungültige Eingaben zurückzugeben.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b970a928fb05224f", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses innerhalb des Funktionsschritts „Verify inputs of the forward function“ der Funktion <code>E2E_P22Forward()</code> im AUTOSAR E2E-Protokoll (Profile 22).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontext</strong>: <code>E2E_P22Forward()</code>\n</li><li><strong>Eingangsparameter / Entitäten</strong>:\n<ul class=\"fig-list\"><li><code>Config</code>: Zeiger auf Konfigurationsstruktur (<code>E2E_P22ConfigType</code>), enthält <code>DataLength</code>\n</li><li><code>State</code>: Zeiger auf Zustandsstruktur (<code>E2E_P22ProtectStateType</code>)\n</li><li><code>Data</code>: Zeiger auf die Nutzdaten (<code>uint8*</code>)\n</li><li><code>ForwardStatus</code>: Status des Weiterleitungsaufrufs (<code>E2E_PCheckStatusType</code>)\n</li><li><code>Length</code>: Länge der übergebenen Daten (<code>uint16</code>)\n</li><li><code>Offset</code>: Offset-Konfiguration innerhalb der Datenstruktur\n</li></ul>\n</li><li><strong>Entscheidungsknoten (Decision Nodes)</strong>:\n<ul class=\"fig-list\"><li>Null-Pointer-Prüfung aller Zeigerparameter (<code>Config</code>, <code>State</code>, <code>Data</code>, <code>ForwardStatus</code>)\n</li><li>Plausibilitätsprüfung für <code>Length</code> und Gültigkeitsprüfung von <code>ForwardStatus</code>\n</li></ul>\n</li><li><strong>Aktivitätsendknoten (Flow Final Nodes)</strong>:\n<ul class=\"fig-list\"><li><code>no input</code>: Fehlerpfad bei Null-Pointer (führt zu <code>E2E_E_INPUTERR_NULL</code>)\n</li><li><code>wrong input</code>: Fehlerpfad bei ungültiger Datenlänge oder fehlenden Neudaten (führt zu <code>E2E_E_INPUTERR_WRONG</code>)\n</li><li><code>input ok</code>: Erfolgreiche Validierung aller Eingabeparameter (führt zur Fortsetzung der Funktionsausführung)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Beginn am Startknoten der Aktivität <code>E2E_P22Forward()</code>.\n</li><li>Erste Verzweigung (Null-Pointer-Check):\n<ul class=\"fig-list\"><li>Auswertung der Guard-Bedingung <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL) &amp;&amp; (ForwardStatus != NULL)</code>.\n</li><li>Bei <code>[FALSE]</code> verzweigt der Kontrollfluss zum Aktivitätsendknoten <code>no input</code>.\n</li><li>Bei <code>[TRUE]</code> führt der Kontrollfluss zum zweiten Entscheidungsknoten.\n</li></ul>\n</li><li>Zweite Verzweigung (Plausibilitäts-Check):\n<ul class=\"fig-list\"><li>Auswertung der Guard-Bedingung <code>Length == Config-&gt;DataLength/8 &amp;&amp; Length &gt;= Offset+2 &amp;&amp; (ForwardStatus != E2E_P_NONEWDATA)</code>.\n</li><li>Bei <code>[FALSE]</code> verzweigt der Kontrollfluss zum Aktivitätsendknoten <code>wrong input</code>.\n</li><li>Bei <code>[TRUE]</code> führt der Kontrollfluss zum Aktivitätsendknoten <code>input ok</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert normativ (referenziert über <code>[PRS_E2E_00636]</code>) das genaue Validierungsverhalten von <code>E2E_P22Forward()</code>. Implementierungen müssen zwingend zuerst sämtliche Zeiger auf Ungleichheit mit <code>NULL</code> prüfen, bevor auf Member von <code>Config</code> zugegriffen werden darf (Vermeidung von Null-Pointer-Dereferenzierungen). Nur wenn sowohl die Datenlänge exakt <code>Config-&gt;DataLength/8</code> entspricht, mindestens <code>Offset+2</code> beträgt und <code>ForwardStatus</code> ungleich <code>E2E_P_NONEWDATA</code> ist, gilt die Eingabe als gültig (<code>input ok</code>). Andernfalls sind die spezifischen Fehlercodes für Null-Pointer bzw. ungültige Eingaben zurückzugeben.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-f1ca5bb0cdf1176b", "to": "FIG-b970a928fb05224f", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
